-- 2026-11-01d: MP Background timelines for batch 19, 25 more current MPs (owner's approval, "yes", 1 Nov 2026).
-- Sets background_timeline (295 entries, copied exactly from "background-batch19.json", which is not committed) and
-- background_last_checked = 2026-11-01 for member_ids 4943, 4976, 4981, 4993, 4995, 5001, 5010, 5025, 5028, 5029, 5030, 5031, 5032, 5033, 5034, 5035, 5036, 5040, 5041, 5042, 5043, 5044, 5045, 5046, 5047,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate(). Every source link was checked by Cowork
-- before the data file was written.
-- Nothing else changes. No code change. Backup of the 25 rows, off the repo: "Claude outputs/backups/2026-11-01d-mp-biography-before.csv".
-- Guards (RAISE): exactly 25 rows change, all of them these 25; the 396 existing timelines are unchanged (md5);
-- MPs with a timeline go from 396 to 421; each array equals the file exactly; 5737 entries in all afterwards.
-- Undo: 2026-11-01d-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (4943, 4976, 4981, 4993, 4995, 5001, 5010, 5025, 5028, 5029, 5030, 5031, 5032, 5033, 5034, 5035, 5036, 5040, 5041, 5042, 5043, 5044, 5045, 5046, 5047)) <> 25 THEN RAISE EXCEPTION 'expected 25 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (4943, 4976, 4981, 4993, 4995, 5001, 5010, 5025, 5028, 5029, 5030, 5031, 5032, 5033, 5034, 5035, 5036, 5040, 5041, 5042, 5043, 5044, 5045, 5046, 5047) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 396 THEN RAISE EXCEPTION 'expected 396 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
