  (5032, 16, $bt$[{"phase":"education","start":null,"end":null,"title":"BSc (Hons) Biochemistry","organisation":"Newcastle University","detail":"First in his family to go to university.","source":{"title":"Tom Gordon MP: About Tom","url":"https://www.tomgordon.org.uk/about-tom"}},{"phase":"education","start":null,"end":null,"title":"Master of Public Health (MPH)","organisation":"Newcastle University","detail":"Studied the degree part time over two years to care for his mother after her breast cancer diagnosis.","source":{"title":"BBC News: 'My mum's cancer struggle got me into politics'","url":"https://www.bbc.co.uk/news/articles/cw5ydg03edko"}},{"phase":"career","start":null,"end":null,"title":"Parliamentary intern","organisation":"House of Lords","detail":"Became a parliamentary intern at the House of Lords aged 20 after meeting Baroness Harris of Richmond.","source":{"title":"The Stray Ferret: The Lib Dem aiming to become Harrogate and Knaresborough's next MP","url":"https://thestrayferret.co.uk/the-lib-dem-aiming-to-become-harrogate-and-knaresboroughs-next-mp/"}},{"phase":"career","start":null,"end":null,"title":"Estate agent","organisation":null,"detail":"Worked as an estate agent.","source":{"title":"The Stray Ferret: The Lib Dem aiming to become Harrogate and Knaresborough's next MP","url":"https://thestrayferret.co.uk/the-lib-dem-aiming-to-become-harrogate-and-knaresboroughs-next-mp/"}},{"phase":"career","start":null,"end":null,"title":"Scientific recruitment and health services research","organisation":null,"detail":"Worked in the scientific recruitment and health services research sector after university.","source":{"title":"Tom Gordon MP: About Tom","url":"https://www.tomgordon.org.uk/about-tom"}},{"phase":"career","start":null,"end":null,"title":"Job at the University of York","organisation":"University of York","detail":"Took a job at the University of York and returned to Knottingley.","source":{"title":"Wikipedia: Tom Gordon","url":"https://en.wikiped